// ============================================================================
// Atlus FlowScript Bytecode Virtual Machine Engine (scrScriptProcess.cpp)
// ============================================================================

// Semantic draft only; exact byte reproduction is provided by the raw wrapper.
[[maybe_unused]] static s32 FlowScript_ExecuteOpcode_Draft(void* script_ctx) {
    if (script_ctx == nullptr) {
        return -1;
    }

    // 99-case branch table for FlowScript bytecode opcodes (0x00..0x63):
    // Handles stack evaluation, variable storage, arithmetic, comparisons,
    // flow jumps, message calls, and native host command hooks.
    struct VMContext {
        u8 pad_00[0x0C];
        u32 opcode;                     // +0x0C
    };

    auto* vm = reinterpret_cast<VMContext*>(script_ctx);
    u32 op = vm->opcode;

    if (op >= 0x63) {
        // Unknown or out-of-range FlowScript instruction
        return 0;
    }

    switch (op) {
        case 0x00: // NOP / END
            return 0;
        case 0x01: // GOTO
        case 0x02: // JIF (Jump If False)
        case 0x03: // JIT (Jump If True)
        case 0x04: // PUSH_IMM
        case 0x05: // PUSH_VAR
        case 0x06: // POP_VAR
        case 0x07: // ADD
        case 0x08: // SUB
        case 0x09: // MUL
        case 0x0A: // DIV
        case 0x0B: // MOD
        case 0x0C: // CMP_EQ
        case 0x0D: // CMP_NE
        case 0x0E: // CMP_LT
        case 0x0F: // CMP_LE
        case 0x10: // CMP_GT
        case 0x11: // CMP_GE
        case 0x12: // AND
        case 0x13: // OR
        case 0x14: // NOT
        case 0x15: // CALL_FUNC
        case 0x16: // RETURN
        case 0x17: // MSG_OPEN
        case 0x18: // MSG_SELECT
        case 0x19: // SET_FLAG
        case 0x1A: // GET_FLAG
        default:
            return 1;
    }
}

// This ledger label/signature is not supported by the machine code: the
// function ignores both incoming arguments and dispatches on the first word
// of the object reached through g_MapSceneView (global pointer slot 0x447E88).
// The word at +0 is the state index, +4 is a phase/substate, and +8 is a
// per-state counter. The view's camera/current and target vectors at +0x1c
// and +0x28 are already independently established by MapSceneView users.
struct FlowScriptOpcodeEvaluatorViewPrefix {
    u32 state;                           // +0x00: 0x27-entry state dispatch
    u32 phase;                           // +0x04: compared against 0..3
    u32 frame;                           // +0x08: incremented by state handlers
    u8  pad_00c[0x10];
    f32 current[3];                      // +0x1c..+0x24
    f32 target[3];                       // +0x28..+0x30
};
static_assert(offsetof(FlowScriptOpcodeEvaluatorViewPrefix, current) == 0x1c);
static_assert(offsetof(FlowScriptOpcodeEvaluatorViewPrefix, target) == 0x28);

// Raw branch destinations from the 39-word ARM jump table at 0x00271570.
// Repeated 0x00271790 entries share the common in-function return path.
[[maybe_unused]] static constexpr u32
kFlowScriptOpcodeEvaluatorStateEntry[0x27] = {
    0x00271790, 0x0027160c, 0x0027161c, 0x002716c0, 0x002716d0, 0x002717c8,
    0x002719e8, 0x00271d58, 0x00271790, 0x00271d68, 0x00271790, 0x00271d78,
    0x00271790, 0x00271d88, 0x00271790, 0x00271d98, 0x00271790, 0x00271da8,
    0x00271790, 0x00271df4, 0x00271790, 0x00271e04, 0x00271790, 0x00271e14,
    0x00271ff8, 0x00272214, 0x002722bc, 0x00271790, 0x0027245c, 0x002726c4,
    0x002726e0, 0x00272754, 0x00272a4c, 0x00272bdc, 0x00272c48, 0x00272ed4,
    0x00272fe4, 0x002732a0, 0x002734a8,
};

// Semantic draft only. It records the verified dispatch, the common-return
// states, and one concrete interpolation operation. The remaining cases call
// engine, event, and UI helpers and mutate additional fields; those handlers
// are intentionally not guessed here.
[[maybe_unused]] static void FlowScript_OpcodeEvaluator_Draft(
    FlowScriptVmWork* ignored_vm, u32 ignored_opcode) {
    (void)ignored_vm;
    (void)ignored_opcode;

    auto* const view = reinterpret_cast<FlowScriptOpcodeEvaluatorViewPrefix*>(
        smt4::engine::g_MapSceneView);
    const u32 state = view->state;
    if (state >= 0x27) {
        return;                            // cmp/ldrlo at 0x00271564..0x0027156c
    }
    if (kFlowScriptOpcodeEvaluatorStateEntry[state] == 0x00271790) {
        return;                            // shared epilogue for these states
    }

    switch (state) {
        case 4:
            // 0x002716f0..0x00271728: current approaches target by 1/3,
            // 1/6, 1/3 on the three axes (ARM VMLA updates).
            view->current[0] += (view->target[0] - view->current[0]) / 3.0f;
            view->current[1] += (view->target[1] - view->current[1]) / 6.0f;
            view->current[2] += (view->target[2] - view->current[2]) / 3.0f;
            // Phase/counter thresholds and subsequent callbacks at
            // 0x0027172c..0x002717bc are observed but not modeled here.
            break;
        default:
            // The table proves a handler entry address for this state, but its
            // engine-side behavior has not yet been reconstructed.
            break;
    }
}

